First, create a context to manage the tooltip state:

```jsx
import React, { createContext, useState } from 'react';

export const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const closeTooltip = () => {
    setTooltip(null);
  };

  const value = { tooltip, setTooltip, closeTooltip };

  return (
    <TooltipContext.Provider value={value}>{children}</TooltipContext.Provider>
  );
};
```

Then, create the Tooltip component:

```jsx
import React, { useContext } from 'react';
import TooltipContext from './TooltipContext';

const Tooltip = ({ children, placement }) => {
  const { tooltip, setTooltip, closeTooltip } = useContext(TooltipContext);

  const handleMouseEnter = () => {
    if (!tooltip) {
      setTooltip({ children, placement });
    }
  };

  const handleMouseLeave = () => {
    if (tooltip && tooltip.children === children) {
      closeTooltip();
    }
  };

  return (
    <div
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      className="relative"
    >
      {tooltip && (
        <div
          className={`absolute z-10 ${placement} bg-white text-black rounded-lg shadow-md p-2`}
          role="tooltip"
        >
          {tooltip.children}
        </div>
      )}
      {children}
    </div>
  );
};

export default Tooltip;
```

Now, you can use the Tooltip component in your NextJS app:

```jsx
import Tooltip from '../components/Tooltip';

const MyComponent = () => {
  return (
    <TooltipProvider>
      <div>
        Hover over me to see the tooltip!
        <Tooltip placement="top">This is a tooltip</Tooltip>
      </div>
    </TooltipProvider>
  );
};

export default MyComponent;
```

