```

3. Update the `csv-downloader.js` route file:

```javascript
import Route from '@ember/routing/route';
import { inject as service } from '@ember/service';
import { task } from 'ember-concurrency';

export default class CsvDownloaderRoute extends Route {
  @service webWorker;

  async model() {
    // Fetch data from an API or any other source
    const data = await fetch('https://api.example.com/data').then(res => res.json());
    return data;
  }

  @task
  *downloadCSV() {
    const { webWorker } = this;
    const data = this.model;

    // Create a Blob from the data
    const csvData = this.createCSV(data);

    // Create a URL for the Blob
    const url = window.URL.createObjectURL(csvData);

    // Save the file with a user-friendly name
    const a = document.createElement('a');
    a.href = url;
    a.download = 'data.csv';
    a.click();

    // Clean up the URL and the Blob
    window.URL.revokeObjectURL(url);
  }

  createCSV(data) {
    const headers = Object.keys(data[0]);
    const rows = data.map(row => headers.map(header => row[header]).join(','));
